CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS worlds (id TEXT PRIMARY KEY, seed TEXT NOT NULL, cycle BIGINT NOT NULL, mode TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS checkpoints (world_id TEXT PRIMARY KEY REFERENCES worlds(id), cycle BIGINT NOT NULL, state TEXT NOT NULL, digest TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS entities (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), name TEXT NOT NULL, type TEXT NOT NULL, owner TEXT NOT NULL, cash BIGINT NOT NULL CHECK(cash>=0), state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS inventories (entity_id TEXT NOT NULL REFERENCES entities(id), good TEXT NOT NULL, quantity BIGINT NOT NULL CHECK(quantity>=0), PRIMARY KEY(entity_id,good));
CREATE TABLE IF NOT EXISTS economic_transactions (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), cycle BIGINT NOT NULL, debit TEXT NOT NULL REFERENCES entities(id), credit TEXT NOT NULL REFERENCES entities(id), amount BIGINT NOT NULL CHECK(amount>0), asset TEXT NOT NULL, reason TEXT NOT NULL, CHECK(debit<>credit));
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, world_id TEXT NOT NULL REFERENCES worlds(id), sequence BIGINT NOT NULL, cycle BIGINT NOT NULL, type TEXT NOT NULL, entity_id TEXT REFERENCES entities(id), data TEXT NOT NULL, UNIQUE(world_id,sequence));
CREATE TABLE IF NOT EXISTS agent_decisions (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES entities(id), cycle BIGINT NOT NULL, status TEXT NOT NULL, context TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS employment (id TEXT PRIMARY KEY, business TEXT NOT NULL REFERENCES entities(id), person TEXT UNIQUE NOT NULL REFERENCES entities(id), wage BIGINT NOT NULL CHECK(wage>0), state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS business_ownership (owner TEXT NOT NULL REFERENCES entities(id), entity TEXT NOT NULL REFERENCES entities(id), bps INTEGER NOT NULL CHECK(bps>0 AND bps<=10000), PRIMARY KEY(owner,entity), CHECK(owner<>entity));
CREATE TABLE IF NOT EXISTS sponsorships (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES entities(id), amount BIGINT NOT NULL CHECK(amount>0), sender TEXT NOT NULL, tx_hash TEXT UNIQUE, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS chain_receipts (tx_hash TEXT PRIMARY KEY, block_height BIGINT NOT NULL, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS settlement_batches (id TEXT PRIMARY KEY, cycle BIGINT NOT NULL, status TEXT NOT NULL, tx_hash TEXT UNIQUE, payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS ledger_by_cycle ON economic_transactions(world_id,cycle);
CREATE INDEX IF NOT EXISTS events_by_entity ON events(entity_id,cycle);
CREATE INDEX IF NOT EXISTS decisions_by_entity ON agent_decisions(entity_id,cycle);
CREATE INDEX IF NOT EXISTS entities_by_owner ON entities(owner);
CREATE TABLE IF NOT EXISTS marketplace_listings (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES entities(id), seller TEXT NOT NULL, ask BIGINT NOT NULL CHECK(ask>0), status TEXT NOT NULL, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS marketplace_offers (id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES entities(id), buyer TEXT NOT NULL, amount BIGINT NOT NULL CHECK(amount>0), status TEXT NOT NULL, state TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS market_prices (world_id TEXT NOT NULL REFERENCES worlds(id), cycle BIGINT NOT NULL, good TEXT NOT NULL, price BIGINT NOT NULL CHECK(price>0), PRIMARY KEY(world_id,cycle,good));
CREATE TABLE IF NOT EXISTS nft_mappings (entity_id TEXT PRIMARY KEY REFERENCES entities(id), contract TEXT NOT NULL, token_id TEXT NOT NULL, owner TEXT NOT NULL, UNIQUE(contract,token_id));
